let accountUser=null,accountRevision=0,accountServer=false,accountSyncing=false,accountPending=false,accountTimer=null;
const baseSave=save;save=function(){baseSave();if(accountUser){clearTimeout(accountTimer);accountTimer=setTimeout(syncAccount,1200)}};
function blankProgress(){return {target:50,units:lessons.map(()=>({attempts:0,correct:0,history:[],read:[],passed:false,due:0,misses:[]}))}}
async function accountAPI(path,options={}){const r=await fetch('api/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Student accounts are not enabled on this static host. Your teacher needs to deploy the included account server to an HTTPS host. Guest lessons are available now.');const d=await r.json();if(!r.ok)throw Error(d.error||'Account request failed.');return d}
async function syncAccount(){if(!accountUser)return;if(accountSyncing){accountPending=true;return}accountSyncing=true;const snapshot=JSON.parse(JSON.stringify(state));try{const d=await accountAPI('progress',{method:'PUT',body:JSON.stringify({data:snapshot,revision:accountRevision})});accountRevision=d.revision;const status=document.querySelector('.local');if(status)status.textContent='● Synced to student account'}catch(e){toast(e.message);const status=document.querySelector('.local');if(status)status.textContent='● Local backup saved · sync pending'}finally{accountSyncing=false;if(accountPending){accountPending=false;syncAccount()}}}
async function loadAccount(user){const d=await accountAPI('progress');accountUser=user;accountRevision=d.revision;storageKey='footpath-user-'+user.id;state=d.data||blankProgress();try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{}updateAccountButton();render();const status=document.querySelector('.local');if(status)status.textContent='● Student account · progress sync enabled'}
function updateAccountButton(){const b=document.querySelector('#account-open');if(b)b.textContent=accountUser?accountUser.label:'Student sign-in'}
async function showAccount(){const body=$('#modalbody');$('#modal').showModal();body.innerHTML='<h2>Student access · 学生入口</h2><p>Checking account service…</p>';try{const d=await accountAPI('me');accountServer=true;if(d.user&&!accountUser)await loadAccount(d.user);if(accountUser){body.innerHTML=`<h2>${escape(accountUser.label)}</h2><p>Signed in as ${escape(accountUser.username)} · ${accountUser.role==='teacher'?'Teacher':'Student'}</p><div class="readingtools"><button id="account-save">Save progress now</button><button id="account-reload">Load account progress</button><button id="account-logout">Sign out</button></div>${accountUser.role==='teacher'?'<h3>Register a student</h3><p class="sub">Use a pseudonymous student ID, not a phone number or email. Share credentials privately with the student or guardian.</p><form id="student-create"><label>Student ID<input id="student-id" type="text" required pattern="[a-zA-Z0-9_-]{3,40}" placeholder="student-001" autocomplete="off"></label><label>Display label<input id="student-label" type="text" maxlength="60" required placeholder="Student 001"></label><label>Initial password<input id="student-password" type="password" minlength="10" maxlength="200" required autocomplete="new-password"></label><button class="primary">Create student account</button></form><div id="student-list"></div>':''}<div id="account-feedback" role="status"></div>`;if(accountUser.role==='teacher')await loadStudents();}else{body.innerHTML='<h2>Student sign-in · 学生登录</h2><p class="sub">Use the student ID and password your teacher gave you. No email or phone number is needed.</p><form id="account-login"><label>Student or teacher ID<input id="login-id" type="text" required autocomplete="username"></label><label>Password<input id="login-password" type="password" required autocomplete="current-password"></label><button class="primary">Sign in →</button></form><div id="account-feedback" role="status"></div>'}}catch(e){body.innerHTML=`<h2>Guest learning is ready.</h2><p>${escape(e.message)}</p><p>Student registration and cross-device progress are not live on this deployment yet. Keep using the lessons as a guest; progress stays on this browser. The source includes a teacher-managed account server for a suitable host.</p>`}}
async function loadStudents(){const d=await accountAPI('students');$('#student-list').innerHTML=`<h3>Your students · ${d.students.length}</h3>${d.students.map(s=>`<article class="studentrow"><b>${escape(s.label)}</b><p>${escape(s.username)} · ${s.attempts} attempts · ${s.mastered}/10 school milestones</p><button class="secondary" data-reset-student="${escape(s.id)}">Reset password</button></article>`).join('')||'<p class="sub">No students registered yet.</p>'}`}
const accountButton=document.createElement('button');accountButton.id='account-open';accountButton.className='secondary';accountButton.textContent='Student sign-in';document.querySelector('header>div').prepend(accountButton);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='account-open')showAccount();if(b.id==='account-save'){await syncAccount();toast('Account save requested. Check the sync status.')}if(b.id==='account-reload'&&accountUser){try{await loadAccount(accountUser);toast('Account progress loaded.')}catch(e){toast(e.message)}}if(b.id==='account-logout'){if(accountSyncing)return toast('Wait for the current progress save to finish.');try{await syncAccount();await accountAPI('logout',{method:'POST',body:'{}'});accountUser=null;clearTimeout(accountTimer);storageKey='footpath-v1';try{state=JSON.parse(localStorage.getItem(storageKey))||blankProgress()}catch{state=blankProgress()}updateAccountButton();$('#modal').close();render();document.querySelector('.local').textContent='● Saved on this device';toast('Signed out. Guest learning restored.')}catch(e){toast(e.message)}}if(b.dataset.resetStudent){$('#student-list').innerHTML=`<h3>Reset student password</h3><form id="student-reset" data-id="${escape(b.dataset.resetStudent)}"><label>New password<input id="reset-password" type="password" minlength="10" maxlength="200" required autocomplete="new-password"></label><button class="primary">Set new password & sign out existing sessions</button></form>`}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['account-login','student-create','student-reset'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{if(f.id==='account-login'){const d=await accountAPI('login',{method:'POST',body:JSON.stringify({username:$('#login-id').value,password:$('#login-password').value})});$('#login-password').value='';await loadAccount(d.user);await showAccount()}if(f.id==='student-create'){await accountAPI('students',{method:'POST',body:JSON.stringify({username:$('#student-id').value,label:$('#student-label').value,password:$('#student-password').value})});f.reset();await loadStudents();$('#account-feedback').textContent='Student account created. Share the initial password privately.'}if(f.id==='student-reset'){await accountAPI('students/reset',{method:'POST',body:JSON.stringify({id:f.dataset.id,password:$('#reset-password').value})});await loadStudents();$('#account-feedback').textContent='Password reset. Existing student sessions were ended.'}}catch(e){const feedback=$('#account-feedback');if(feedback)feedback.textContent=e.message;else toast(e.message)}finally{b.disabled=false}});
// Check only on demand to avoid account requests while learning offline.
